const setSourceGameFetchFailure = `-- name: SetSourceGameFetchFailure :exec
UPDATE source_games SET
  last_fetched_at = $1,
  last_fetch_result = $2,
  consecutive_fail_days = CASE
    WHEN CAST($3 AS timestamptz) IS NULL THEN 1
    WHEN last_fetched_at::date = CAST($1 AS timestamptz)::date THEN greatest(consecutive_fail_days, 1)
    WHEN last_fetched_at::date = (CAST($1 AS timestamptz) - interval '1 day')::date THEN consecutive_fail_days + 1
    ELSE 1 END
WHERE id = $4
`

type SetSourceGameFetchFailureParams struct {
	LastFetchedAt   *time.Time `json:"last_fetched_at"`
	LastFetchResult string     `json:"last_fetch_result"`
	PreviousFetch   *time.Time `json:"previous_fetch"`
	ID              uuid.UUID  `json:"id"`
}

func (q *Queries) SetSourceGameFetchFailure(ctx context.Context, arg SetSourceGameFetchFailureParams) error {
	_, err := q.db.Exec(ctx, setSourceGameFetchFailure,
		arg.LastFetchedAt,
		arg.LastFetchResult,
		arg.PreviousFetch,
		arg.ID,
	)
	return err
}

